import subprocess
import os

def search_log(pattern: str, logfile: str) -> list[str]:
    if not os.path.isfile(logfile):
        raise FileNotFoundError(f"The file {logfile} does not exist.")

    try:
        result = subprocess.run(['grep', pattern, logfile], capture_output=True, text=True, check=True)
        return result.stdout.strip().split('\n')
    except subprocess.CalledProcessError:
        return []
