import subprocess
import os

def first_lines(filename: str, count: str) -> list[str]:
    if not count.isdigit():
        raise ValueError("count must be a string of decimal digits")
    if count == '0':
        return []
    if not os.path.isfile(filename):
        raise FileNotFoundError(f"The file {filename} does not exist")

    try:
        result = subprocess.run(['head', '-n', count, filename], capture_output=True, text=True, check=True)
        return result.stdout.splitlines()
    except subprocess.CalledProcessError:
        raise FileNotFoundError(f"An error occurred while trying to read the file {filename}")
