import os
import subprocess

def find_files(dirname: str, extension: str) -> list[str]:
    if not os.path.isdir(dirname):
        raise FileNotFoundError(f"The directory {dirname} does not exist or is not a directory.")

    try:
        result = subprocess.run(
            ["find", dirname, "-maxdepth", "1", "-type", "f", "-name", f".{extension}"],
            capture_output=True,
            text=True,
            check=True
        )
        files = result.stdout.strip().split('\n')
        return sorted([file for file in files if file])
    except subprocess.CalledProcessError:
        return []
