import sqlite3

def search_articles(conn, keyword: str, sort_by: str) -> list[str]:
    if sort_by not in ('title', 'published', 'views'):
        raise ValueError("Invalid sort_by value")

    cursor = conn.cursor()
    query = "SELECT title FROM articles WHERE title LIKE ?"
    cursor.execute(query, ('%' + keyword + '%',))
    titles = [row[0] for row in cursor.fetchall()]

    if not titles:
        return []

    if sort_by == 'title':
        titles.sort()
    elif sort_by == 'published':
        titles.sort(key=lambda x: x['published'])
    elif sort_by == 'views':
        titles.sort(key=lambda x: x['views'])

    return titles
